from pathlib import Path

path = Path(__file__).parent / 'reports.html'
text = path.read_text(encoding='utf-8')
marker = 'async function loadAll()'
if 'function centralKind()' in text:
    print('central functions already present')
    raise SystemExit(0)
idx = text.index(marker)
central = r'''function centralKind(){return document.getElementById('central-kind').value}function centralParams(page=1,limit){const p=new URLSearchParams({page:String(page),limit:String(limit||document.getElementById('central-limit').value||20)});const from=document.getElementById('central-from').value,to=document.getElementById('central-to').value;if(from)p.set('from',from);if(to)p.set('to',to);return p}function centralSetStatus(value,type=''){const el=document.getElementById('central-status');el.textContent=value;el.style.color=type==='error'?'var(--danger)':'var(--muted')}function centralUpdateMode(){const all=centralKind().startsWith('all-');document.getElementById('central-entity-field').style.display=all?'none':''}function centralOptionRows(items){const select=document.getElementById('central-entity-select');select.innerHTML='<option value="">اختر الجهة</option>'+items.map(item=>`<option value="${esc(item.id)}">${esc(item.name)}${item.barcode?' — '+esc(item.barcode):''}</option>`).join('');select.disabled=!items.length}async function searchCentralEntities(){const kind=centralKind(),term=document.getElementById('central-entity-search').value.trim();if(term.length<2)return toast('اكتب حرفين على الأقل للبحث','warning');const endpoint=kind==='customer'?'/customers':kind==='supplier'?'/suppliers':'/products/search';const params=new URLSearchParams(kind==='product'?{term,limit:'20'}:{search:term,limit:'50',page:'1'});try{centralSetStatus('جاري البحث');const r=await fetch(`${API}${endpoint}?${params}`,{headers:auth()}),d=await r.json();if(!r.ok)throw Error(d.error||'فشل البحث');const rows=kind==='product'?(d.results||d.products||[]):(d.customers||d.suppliers||[]);centralOptionRows(rows);centralSetStatus(rows.length?`تم العثور على ${rows.length} نتيجة`:'لا توجد نتائج')}catch(e){centralSetStatus(e.message,'error');toast(e.message,'error')}}function centralEntityId(){return document.getElementById('central-entity-select').value}function centralStatementUrl(kind,page=1,limit=20){const p=centralParams(page,limit);if(kind==='customer'){p.set('customer_id',centralEntityId());return `${API}/customers/statement?${p}`}if(kind==='supplier'){p.set('supplier_id',centralEntityId());return `${API}/suppliers/statement?${p}`}return `${API}/products/${centralEntityId()}/stock-movements?${p}`}function centralTypeLabel(value){return ({sale:'بيع',payment:'سداد',purchase:'شراء',return:'مرتجع',supplier_payment:'سداد مورد'}[value]||value||'حركة')}function renderCentralRows(kind,rows){if(!rows.length)return '<div class="empty">لا توجد بيانات خلال الفترة المحددة</div>';if(kind==='product')return `<div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>التاريخ</th><th>العملية</th><th>الرصيد قبل</th><th>التغيير</th><th>الرصيد بعد / النهائي</th><th>المرجع</th><th>الملاحظة</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.created_at||'')}</td><td>${esc(centralTypeLabel(r.reference_type))}</td><td>${formatPosNumber(Number(r.old_quantity||0))}</td><td>${formatPosNumber(Number(r.quantity_change||0))}</td><td><strong>${formatPosNumber(Number(r.new_quantity||0))}</strong></td><td>${r.reference_id?'#'+esc(r.reference_id):'-'}</td><td>${esc(r.note||'-')}</td></tr>`).join('')}</tbody></table></div>`;if(kind==='all')return `<div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>الجهة</th><th>الهاتف</th><th>الرصيد / المتبقي</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td><strong>${esc(r.name||r.invoice_number||'-')}</strong></td><td>${esc(r.phone||r.note||'-')}</td><td>${formatPosMoney(Number(r.balance??r.amount??0))}</td></tr>`).join('')}</tbody></table></div>`;let running=0;return `<div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>التاريخ</th><th>النوع</th><th>رقم المرجع</th><th>مدين / زيادة</th><th>دائن / تخفيض</th><th>الرصيد التراكمي</th><th>ملاحظة</th></tr></thead><tbody>${rows.map((r,i)=>{const amount=Number(r.amount??r.total_amount??0);const debit=(kind==='customer'&&r.type==='sale')||(kind==='supplier'&&r.type==='purchase')?amount:0;const credit=amount-debit;running+=debit-credit;return `<tr><td>${i+1}</td><td>${esc(r.created_at||'')}</td><td>${esc(centralTypeLabel(r.type))}</td><td>${esc(r.invoice_number||'-')}</td><td>${formatPosMoney(debit)}</td><td>${formatPosMoney(credit)}</td><td><strong>${formatPosMoney(running)}</strong></td><td>${esc(r.note||r.wallet_name||'-')}</td></tr>`}).join('')}</tbody></table></div>`}function renderCentralSummary(kind,data){const s=data.summary||{};if(kind==='product')return `<div class="metric"><div class="label">الرصيد النهائي الحالي</div><strong>${formatPosNumber(Number(data.closing_balance??data.current_stock??0))}</strong></div><div class="metric"><div class="label">إجمالي الحركات</div><strong>${formatPosNumber(Number(data.pagination?.total||data.movements?.length||0),0)}</strong></div>`;return `<div class="metric"><div class="label">إجمالي الزيادة / المدين</div><strong>${formatPosMoney(Number(s.total_debit||0))}</strong></div><div class="metric"><div class="label">إجمالي التخفيض / الدائن</div><strong>${formatPosMoney(Number(s.total_credit||0))}</strong></div><div class="metric"><div class="label">الرصيد النهائي / المتبقي</div><strong>${formatPosMoney(Number(s.final_balance||0))}</strong></div>`}async function loadCentralStatement(){const kind=centralKind();if(!kind.startsWith('all-')&&!centralEntityId())return toast('ابحث واختر جهة أولًا','warning');const out=document.getElementById('central-output');out.innerHTML='<div class="empty">جاري تحميل الكشف...</div>';centralSetStatus('جاري التحميل');try{if(kind==='all-customers'||kind==='all-suppliers'){const endpoint=kind==='all-customers'?'/customers':'/suppliers';const r=await fetch(`${API}${endpoint}?limit=100&page=1`,{headers:auth()}),d=await r.json();if(!r.ok)throw Error(d.error||'فشل تحميل القائمة');const rows=d.customers||d.suppliers||[];document.getElementById('central-summary').innerHTML=`<div class="metric"><div class="label">عدد الجهات</div><strong>${rows.length}</strong></div><div class="metric"><div class="label">إجمالي الأرصدة</div><strong>${formatPosMoney(rows.reduce((sum,row)=>sum+Number(row.balance||0),0))}</strong></div>`;out.innerHTML=renderCentralRows('all',rows);centralSetStatus('تم التحديث');return}const r=await fetch(centralStatementUrl(kind,1,document.getElementById('central-limit').value),{headers:auth()}),d=await r.json();if(!r.ok)throw Error(d.error||'فشل تحميل الكشف');const rows=d.statement||d.movements||[];document.getElementById('central-summary').innerHTML=renderCentralSummary(kind,d);out.innerHTML=renderCentralRows(kind,rows);centralSetStatus(`تم التحديث — ${rows.length} صف`)}catch(e){out.innerHTML=`<div class="empty" style="color:var(--danger)">${esc(e.message)}</div>`;centralSetStatus(e.message,'error')}}async function printCentralStatement(){if(!document.getElementById('central-output').querySelector('table'))await loadCentralStatement();const output=document.getElementById('central-output');if(!output.querySelector('table'))return toast('لا توجد بيانات للطباعة','warning');if(window.POSDocs)POSDocs.printReport(output,{title:'كشف مخصص'}).catch(e=>toast(e.message,'error'));else window.print()}
'''
path.write_text(text[:idx] + central + text[idx:], encoding='utf-8')
print('central reports restored')
